) AS (
  VALUES 
    (503::BIGINT, 'SÚPER BUEN PROFE, deja guías no obligatorias semanales que lo ayudan a entender mejor la materia, los quizes lo preparan para el examen, el profe siempre ayuda si le escribe con una duda y deja todo super claro, fue la primer vez que llevé CDI y aprendí demasiado con él. 100% recomendado'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-07-21T00:00:00+00:00'::TIMESTAMPTZ, '9b6a8517c14471933d964c000f51c31fc6b0405d2522c993f3dc0b41911030db'::TEXT, ARRAY[605]::BIGINT[]),
    (503::BIGINT, 'A mi parecer muy buen profe, no le va a regalar el curso pero usted va a entender muy bien la materia, más si hace las guías semanales (son opcionales, no las evalúa) se preocupa por que los estudiantes entiendan. Llevaría otras materias con el de fijo.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2026-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'bb274651188086be83e1b9c9e778811c7440c8673d4ffedc263d5f3c9b627a84'::TEXT, ARRAY[605]::BIGINT[]),
    (503::BIGINT, 'Sus clases se vuelven tediosas solo explica ejercicios, se come pasos y va extremadamente rápido, no lo recomiendo si nunca a llevado CDI porque te vas a perder. Siento que califica duro hace quizzes cada semana y deja práctica semales. La calificación de aca esta mal hay mejores profes'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos']::TEXT[], '2026-06-06T00:00:00+00:00'::TIMESTAMPTZ, '3bc327d9fb883f2212047fac591e5621abbdd6a12b33d9505d454b4dd4388af7'::TEXT, ARRAY[605]::BIGINT[]),
    (503::BIGINT, 'A mi en lo personal, me encantó su forma de explicar. Es directo, pero no se salta nada, cubre todo y con buenos ejercicios. Discreta es un curso pesado, pero él lo hace ver muy sencillo porque te da trucos para resolver los ejercicios. El Goat definitivamente.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2026-06-03T00:00:00+00:00'::TIMESTAMPTZ, 'c6bf62477772c136f88cb8f099fef84ae1093e86e24e43d141b1e043a95ecd06'::TEXT, ARRAY[1018]::BIGINT[]),
    (503::BIGINT, 'Es un cagué de risa las clases, y lo mejor es que no se desvía del tema solo porque sí, no pierde el tiempo y se le entiende todo claramente, súper considerado, corrige de manera divertida. Sencillamente, si usted quiere pasar el curso con él, haga lo que el mae le diga, porque él sabe lo que dice.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-05-13T00:00:00+00:00'::TIMESTAMPTZ, '471ad4f2a21572f74f4dcd4f149ab6cbfeda24e503b585085c44da86cf58b21f'::TEXT, ARRAY[1018]::BIGINT[]),
    (503::BIGINT, 'El mae se nota que le gusta lo que hace, no solo da conceptos y métodos, explica razonamiento y el porqué de las cosas. "Vamos justos de tiempo"'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-02-09T00:00:00+00:00'::TIMESTAMPTZ, '0b5f6b3c1b2ce84e043fada59158d56daef53c9c026f68e133ee20232a72e213'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'El mejor profesor de matemáticas del tec, increíblemente bueno. Sabe muchisisisismo de la materia y es muy consciente con los estudiantes. Enseña de manera exquisita; todas las clases son importantes. Prepara muy bien para los exámenes y deja guías semanales de apoyo. Excelente en todo aspecto.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-02-09T00:00:00+00:00'::TIMESTAMPTZ, 'd6fd19c06486cca7ac592ad89517acc85879239a9831e204398af6c5d7463c06'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'Al repetir el curso con otro profesor noté que simplemente es que este mae complica el curso porque quiere.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Pocos exámenes']::TEXT[], '2026-02-07T00:00:00+00:00'::TIMESTAMPTZ, '01a7ea812c3262607bb5b57a72b8e413c6ffee440d807a47232b299871eb817a'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'Es un muy buen profe, explica muy bien y resuelve dudas, lo recomiendo totalmente'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-01-31T00:00:00+00:00'::TIMESTAMPTZ, '323855a80539fc51c7c05cb251b12bc853b3e52f6e042253215426b73d831b87'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'super mega super super increible recomendado 100% explica super bieny deja miles de materiales de apoyo para que usted pase sin problema.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-01-04T00:00:00+00:00'::TIMESTAMPTZ, '90f1c26b4e359d31cf23bfa14b64ac985975b6064af51f829327a839627c4f00'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'Pésimo profesor.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-23T00:00:00+00:00'::TIMESTAMPTZ, '228e961b0cbe8e7fd3d88c5d4c2de6fe176f95775779e15717c1f8c3a3166ef1'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'Es muy buen profesor. Explica claramente y da materiales de apoyo. Hágale caso cuando dice que practique toda las semanas para ir al día con la materia, es de mucha utilidad. Un poco intimidante, pero ayuda bastante al estudiante.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-17T00:00:00+00:00'::TIMESTAMPTZ, '3b3ae8ed5a1f82c98cae8f4c3f913bb68769b0a1d39f3ad55b7b1f63d8da686a'::TEXT, ARRAY[1018]::BIGINT[]),
    (503::BIGINT, 'Muy buen profesor, explica sumamente bien y si usted le pone y va al día con la materia puede pasar el curso Es un curso exigente que requiere su práctica semanal para ir bien con los temas pero si se puede ganar y con este profesor más porque explica muy bien los temas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-16T00:00:00+00:00'::TIMESTAMPTZ, 'b47c9c8d6839a93b14dd41628cd7f97f6484d74d8213282c071d74e0a74744cf'::TEXT, ARRAY[1018]::BIGINT[]),
    (503::BIGINT, 'Explica bien y se le entiende si usted tiene buenas bases, es grocero al responder preguntas y dudas. No lo recomiendo si es su primera ves en el curso.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2025-12-15T00:00:00+00:00'::TIMESTAMPTZ, 'd22d5d976830ae744a6a443157b5cf90dde813711c1b4f98d698f846e942c82c'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'En lo personal, me parece un buen profesor, era la segunda vez que yo llevaba el curso, entonces ya tenia algunas bases, pero aun asi todo lo explico de una manera bastante clara y practica.Da enfasis en practicar ejercicios que salen en los parciales y eso ayuda bastante.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-12T00:00:00+00:00'::TIMESTAMPTZ, '98fdb726dd91336e34e01174035ae4e538d35c1d0699dee74cac70e89f84b034'::TEXT, ARRAY[1018]::BIGINT[]),
    (503::BIGINT, 'Mejor profe de mi vida, falte como a 5 clases y llegué de goma como a 3 y nunca me atrasé en la materia por todo el material de apoyo que brinda.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-12T00:00:00+00:00'::TIMESTAMPTZ, 'ade36fff853cce0f5e1d697267d8693e968c9049c63dcea02b2de0ea3ff94208'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'Buen profe, si se le presta atención durante las 16 semanas va muy bien preparado a los exámenes, la guía de la cátedra puede ser confusa por lo que recomiendo intente ir a todas las clases o ver grabaciones de la clase de el si tiene.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-12T00:00:00+00:00'::TIMESTAMPTZ, '326b79cd6692e4f650f9075e6c8dfa84f078cec931887b376034418d80b73320'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-12T00:00:00+00:00'::TIMESTAMPTZ, '31b0a1499f9ec5886b822f05cbb11d4511e812bb87a4a043be30ebf42ed61ea7'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'Excelente profesor, hace que sus clases sean fáciles de llevar y explica de una manera asombrosa'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-12T00:00:00+00:00'::TIMESTAMPTZ, '4a015109d19acea8b0f599d7ac485cae9adda428c9210e990b04220288694d3d'::TEXT, ARRAY[1018]::BIGINT[]),
    (503::BIGINT, 'Excelente Profesor, explicaciones muy buenas y claras, bastante objetivo, su evaluación es justa.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Clases excelentes']::TEXT[], '2025-12-12T00:00:00+00:00'::TIMESTAMPTZ, 'aa4047603eaebefb3a7bd8a37fea7a2b5d407046b99935d0d0bdc2212cead364'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'Asume que uno sabe la materia y lo trata despectivamente si no entiende. No se pueden apelar los examenes porque es cero flexible y es lo que él dice y punto. Bueno quizas trata mal a los que les cuesta y beneficia a los que les va bien sin esfuerzo y por eso tantos comentarios positivos.'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2025-12-12T00:00:00+00:00'::TIMESTAMPTZ, 'acb25a5f8659a8c45923458e231935ea3d814ab6afcc473c3e3ee834d634581f'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'CAL es considerado fácil, solo es mucha materia muy distinta, por esto avanza "rápido". Explica muy claro y sabe demasiado bien lo que dice. Califica justo; normalmente hace 6 quizzes similares al examen, usa bien tecDigital y califica rápido. He llevado dos cursos con él y llevaría todos si pudiera'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-12-12T00:00:00+00:00'::TIMESTAMPTZ, '5b6b7a3ff2009e542e1224d6de79bd0f2bd0961cdce6fce6d451674e6f180d40'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'Da las clases super claras y siempre ayuda en todo, deja los temas de quices en telegram entonces siempre se sabe que va a salir, y deja quices sobre lo que se vio, no le va a preguntar algo distinto.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Brinda apoyo']::TEXT[], '2025-12-12T00:00:00+00:00'::TIMESTAMPTZ, '5840a54520b438ed5b8924a2d72f5f39687e0ebd87e51a6100c76ac88757db47'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'Un profe excepcional, es pura vida, y sabe explicar no solo los temas, sino para qué sirven. Brinda bastantes recursos de apoyo para prepararse para los parciales y quices, donde, a pesar de calificar duro, califica justo.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Brinda apoyo']::TEXT[], '2025-12-12T00:00:00+00:00'::TIMESTAMPTZ, 'a1e8e4d7331be5807b1d14387d3d5c89a67cf34e3363b258c56bc3094d5a00da'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'Muy buen profesor, se esfuerza mucho y las clases suelen ser muy dinámicas, además de que ciertos temas los termina explicando de más y eso ayuda bastante. En mi caso no me fue muy bien pero no fue culpa del profesor'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('40','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-12T00:00:00+00:00'::TIMESTAMPTZ, 'b83a6757e65f34ad84a49ca2ad324b6f2650f8a87496197012ae1e94b84f8706'::TEXT, ARRAY[1018]::BIGINT[]),
    (503::BIGINT, 'Excelente profesor. Explica bien y se preocupa que el estudiante vaya bastante preparado para el examen. Además, buena persona y llevadero.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-12T00:00:00+00:00'::TIMESTAMPTZ, '21baa7f1575dd5370431b7f104bb2112bd504dfe5f076ada9ba42839b1fe8243'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'Hace el mínimo de quices y los ejercicios de estos a veces eran más complicados que en un examen, no enseña mal pero tampoco es una cosa excepcional pues va demasiado rápido, califica normal. No lo recomiendo para alguien que lleva el curso por primera vez'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2025-12-11T00:00:00+00:00'::TIMESTAMPTZ, 'ba787a864cb65634dadc9dd04657632fe8fd1ad053cf42288a49e35bb602e66c'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'Se supone que es el cálculo más fácil pero lo sentí confuso... Si preguntas algo te hace sentir como un baboso. No hace presentaciones y su letra casi no se entiende si te sientas atrás. Tiene sus cosas buenas pero no llevaría otro curso con él'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Aspectos de calificación claros']::TEXT[], '2025-12-06T00:00:00+00:00'::TIMESTAMPTZ, '10e391c77b573ec1b09c799f372fc085aa2ed189a63c506a8419d08f90abd671'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'Es un excelente profe, explica muy bien y se preocupa por que el estudiante entienda, solo siento que califica muy duro, es el típico profe que no da ni un punto por intentarlo.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes']::TEXT[], '2025-07-28T00:00:00+00:00'::TIMESTAMPTZ, 'b4265a49de19284a1662df6c2accd2902c7f88e669352b73261e454b5e95dd76'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Es muy buen profe, explica todo con calma las veces necesarias y responde cualquier duda, deja todo muy claro y sin duda volvería a matricular con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-17T00:00:00+00:00'::TIMESTAMPTZ, '7f452bc3cbc92402f10b9a0edc62f765747a35ea9663f9255ad3dd0a8d74a115'::TEXT, ARRAY[1018]::BIGINT[]),
    (503::BIGINT, 'Explica súper bien, hace bastantes quices, pero estudiando se pasan y siempre avisa cuando los va a hacer . Se comunica por telegram y siempre contesta cuando se tiene alguna duda. Muy recomendado'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Muchos proyectos grupales']::TEXT[], '2025-07-03T00:00:00+00:00'::TIMESTAMPTZ, 'fc989a0a4044f2043537ff2446ac8d236a3ce3683efc8f06bb1d470add443e19'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'Los quiz son muy difíciles pero logrables por la clara explicación que da el en clase, respetuoso y su clase se desenvuelve de manera explicativa y productiva. Hace quiz en los que te obliga a estudiar para el examen. No deja tareas'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Da buena retroalimentación']::TEXT[], '2025-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'c8e1f95abc67784bf0fa58aec82f46547ebad702ffb604eea7b45d503d12c7ca'::TEXT, ARRAY[563]::BIGINT[]),
    (503::BIGINT, 'Excelente profe, duro calificando pero siempre por el bien del estudiante. Dispuesto a ayudar, vayan a consulta, él ve en los estudiantes las ganas de entender. Nunca falte a esa clase, cada minuto es súper valioso. Solo hace quices y exámenes, así que si quiere pasar fácil con él no es.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2025-02-04T00:00:00+00:00'::TIMESTAMPTZ, '733535f620e24d0ad1c340a9761c587879b78a434e85a1d0392c21860cf5e556'::TEXT, ARRAY[563]::BIGINT[]),
    (503::BIGINT, 'Juanjo es un profe 10/10. Explica muy bien y prepara a los estudiantes de buena manera. Hace muchos ejercicios y deja bastantes de tarea pero lo hace para reforzar y que usted esté preparado para el examen. CDI es un curso difícil de buenas a primeras, pero con él la probabilidad de pasar aumenta.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2025-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'cc6a4e3560bb3e4d05b156fff04327e15577a24ea7b6f8f3ef59025ca7b00350'::TEXT, ARRAY[605]::BIGINT[]),
    (503::BIGINT, 'Es un muy buen profe, sabe mucho por lo que siempre te va a explicar más y te va a decir el por qué de algún procedimiento a diferencia de otros profes. Da varios ejemplos que usualmente en los quices mete, los quices son difíciles pero eso hace que en los exámenes uno salga bien.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-12-20T00:00:00+00:00'::TIMESTAMPTZ, 'b0bbca353f49b1cd611168f05690a69095e215d288d10fe247a154b2bf101ce5'::TEXT, ARRAY[1018, 563]::BIGINT[]),
    (503::BIGINT, 'Es muy buen profe. Explica super claro y hace valga la pena ir a la clase. Solo hace examenes y quices por lo que si estudia para los quices le va a ir bien. Califica duro pero no te va a intentar quedar. realmente quiere que a uno le vaya bien. Recomendado (aunque tuve que hacer repo para pasar)'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Muchas tareas']::TEXT[], '2024-12-07T00:00:00+00:00'::TIMESTAMPTZ, 'd7038a0a4c3eefa8dea33f3723e8d5348bf0a1b8610445382a8099d0f496f9b9'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Muy buen profe, sabe bastante y va al grano, hace quices de dificultad parecida a los exámenes, lo que hace que estudies antes de los exámenes y vas al día, si estudias bien y sales bien en los quices, el examen se pasa bien, super recomendando.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-12-07T00:00:00+00:00'::TIMESTAMPTZ, 'a8b973a6ea99721e62ce8c2f67d7d8a11551c693cacf5bc05c7c3c75512be72c'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'El profe explica muy bien y sabe mucho pero evalúa fuerte así que hay que prepararse bastante igual recomiendo llevar con el siempre y cuando le ponga bastante al curso.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2024-12-07T00:00:00+00:00'::TIMESTAMPTZ, '3febdd7f78459474b0bde8f9d67224d57971ea13a8c868fa38e5f34123aa42a2'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'El profe es bueno y sabe demasiado, sin embargo, hay veces donde va demasiado rápido y no da tantos ejemplos como uno quisiera. Es importante ir a clases. No repone quices y es medio dolor, pero en general es bueno, uno aprende mucho y si le pone pasa fácil.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes']::TEXT[], '2024-11-19T00:00:00+00:00'::TIMESTAMPTZ, '2f1d71e84ad1bcbdca9c95abf4c64d20c197078be575d63a0b9dd89ca47726e6'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'El profe califica duro, pero explica súper bien. En consulta no explica mucho pero la verdad deja todo súper claro en clase. Los quiz son de mucha ayuda para el parcial. Full pasan si matriculan con el'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-11-09T00:00:00+00:00'::TIMESTAMPTZ, '4ad1b788577341d11d2f908915c9f583caba389365959a80e7632b0a1da4b69b'::TEXT, ARRAY[563]::BIGINT[]),
    (503::BIGINT, 'Él explica genial, es un profesor muy bueno y realmente quiere que usted aprenda. Califica rudo y se le caga bastante en sus errores pero ajá'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-08-26T00:00:00+00:00'::TIMESTAMPTZ, '6343f01f41c511d19a6b28d3859f112f44bf596b32cc236b6d37c71fa5a82bec'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Como profesor es excelente, sus explicaciones son demasiado claras y realmente le importa que ud si aprenda, no es de solo dar las fórmulas él intenta que usted le vea sentido, siempre está dispuesto a ayudar. Sí es exigente calificando pero con que ponga atención en clase con lo que pide todo bien!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, '87bcc2dd141acd590babb7d29773cb54b0b1f1628845350a96176427a3134637'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Explicando es excelente. Lo que no me gustó para nada fue que el 40% del curso fueran 7 quices que si valían bastante. Hay otros profes que ese 40% lo hicieron en kahn academy entonces los estudiantes pueden ganar ese porcentaje y garantizar que están aprendiendo.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos exámenes']::TEXT[], '2024-06-14T00:00:00+00:00'::TIMESTAMPTZ, '9ea005932c8dc00996d2344b4f40d94831104929d9c32069534394e6cdf03aca'::TEXT, ARRAY[2444]::BIGINT[]),
    (503::BIGINT, 'El profe explica muy bien, muy claro y suele ir al punto haciendo ejercicios para el examen.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes']::TEXT[], '2024-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'da930c9c852fc031fac8740481cd101b8da2dfa0eeb792a9c93fbd9638b13d3f'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Excelente profe, siempre ayuda bastante. En sus clases sí se aprende y tiene un canal de YT bueno.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación']::TEXT[], '2024-06-12T00:00:00+00:00'::TIMESTAMPTZ, '49a8d8e4521663f8366a21488d1b9ae20301fde75dd356153edce11202c6e182'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Excelente profe. Dele sin miedo :)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-11T00:00:00+00:00'::TIMESTAMPTZ, '098b7546cbaccadf8448d05d0ba144a4cb117e647ed35ebe7fa6e65fe58a9eeb'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Se basa en el mutuo respeto, el le pone ganas a enseñar bien y que todo quede claro y uno le tiene que prestar atención, procura el bien del estudiante y se le entiende bastante. Si lo encuentra para calculo para administración matricule con él.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-11T00:00:00+00:00'::TIMESTAMPTZ, 'f26b4722928c335ce54f173191d4699d83c180cbfa4e64e85ef56da17e64f745'::TEXT, ARRAY[2444]::BIGINT[]),
    (503::BIGINT, 'Exelente profe, va directo al punto, solo pon atención y pasas el curso facilmente'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-01-29T00:00:00+00:00'::TIMESTAMPTZ, '218946d4dadcad5fc6c27ca3bd390d2d04d43970d5887e822e4f6d55e4f70855'::TEXT, ARRAY[563]::BIGINT[]),
    (503::BIGINT, 'El profesor explica súper bien, se pasa fácil este curso con él. Califica bien, pero tenga cuidado en los quices que pueden ser dificilillos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-01-22T00:00:00+00:00'::TIMESTAMPTZ, 'c9cec01fbff51a388ba4ff89f4d6263a81653501802791f00dee22ef40ba6138'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'De lo mejor que he visto en profesores de mate, si usted de verdad quiere aprender lo super recomiendo, y a como explica califica, así que toca practicar bastante con el.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Clases excelentes']::TEXT[], '2024-01-19T00:00:00+00:00'::TIMESTAMPTZ, 'f2867f4b92735e9c6b2b176237bf1c235ef7ef99e8edb1408477056290215bdb'::TEXT, ARRAY[563]::BIGINT[]),
    (503::BIGINT, 'Es un buen profesor, ayuda bastante si se le pide ayuda y explica de nuevo de ser necesario. Es una buena persona que respeta a sus estudiantes y tiene ganas de que le entiendan la materia, sus quiz son un poco difíciles pero es para prepararlo bien para el examen.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-01-19T00:00:00+00:00'::TIMESTAMPTZ, '6e4d28ee0ef4c1c849f8938d5bf3a0756dc93e244e4edd9d311b4d8a90fa3951'::TEXT, ARRAY[563]::BIGINT[]),
    (503::BIGINT, 'Explica muy bien, todo se le entiende, siento que se enfoca más en la teoría que en práctica en clase, pero todo bien, porque en algunos temas si es necesario! El canal de youtube es muy útil cuando uno falta a clase! Es muy buena persona pero le gusta que le demuestren que le está poniendo al curso'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2024-01-11T00:00:00+00:00'::TIMESTAMPTZ, '67dc7e16d8c3382ea08bf9e43aa675dff05f861e43ed81cdfbd494ac54c8383f'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Si quiere aprender matricule con él, debe llevar al día la materia porque los quices son duros pero lo prepara para el parcial. Es muy ordenado.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-12-07T00:00:00+00:00'::TIMESTAMPTZ, '5a6fafd4ce3efae9ba23df34c8c0fba31561f880d3fe18efa7837f3c64416664'::TEXT, ARRAY[563]::BIGINT[]),
    (503::BIGINT, 'Carece de humanidad. No lo recomiendo'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2023-12-05T00:00:00+00:00'::TIMESTAMPTZ, '2646913fa8c5cdc167a8af9fc21815a646660c0570683e7f4e3e271a30249cc6'::TEXT, ARRAY[563]::BIGINT[]),
    (503::BIGINT, 'Si quiere aprender matricule con el, practique para los exámenes cortos bastante porque si no se lo come, para los examenes él es una joya pero igual practique, eso si, califica duro y más dependiendo del error que usted haya cometido.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2023-12-03T00:00:00+00:00'::TIMESTAMPTZ, '19e2c05fc641d070ea8b470e00111b8f46ae5c1dd9a9dd60beffc1e80099c1a3'::TEXT, ARRAY[563]::BIGINT[]),
    (503::BIGINT, 'Te hace entender la matemática a tal punto que los ejercicios que utiliza en clase son de mayor dificultad de la cátedra. Por eso algunos dicen que los quices son duros, pero lo valen ya que a la hora del parcial se te hace realmente fácil y entendible. Excelente profesor.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2023-11-30T00:00:00+00:00'::TIMESTAMPTZ, '1a7e27934f6f6f9104388f70cae97fe2c8bf22ce864ae3671b6366fe7b0b86d8'::TEXT, ARRAY[563]::BIGINT[]),
    (503::BIGINT, 'El profe es muy bueno, solo sepa que debe sacar mucho provecho a sus clases porque el explica bien y no pierde el tiempo. Como muchos dicen los quices son duros pero para eso le recomiendo estudiar bastante porque me parece que esa es una de las razones por la cual muchos se quejan.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2023-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'a3452dc1e30cc9be9171ac266e19986ec1506ef3bc8dff81eb773e1385fd995d'::TEXT, ARRAY[563]::BIGINT[]),
    (503::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes']::TEXT[], '2023-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'aa1f216a97be4703787aafcb20f9be97641d1f0a88a1d6768dad1a24de2c7836'::TEXT, ARRAY[563]::BIGINT[]),
    (503::BIGINT, 'Súper recomendable, si no tiene buenas bases más bien MATRICULE CON ÉL, enseña desde cero y hace que uno entienda.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-11-24T00:00:00+00:00'::TIMESTAMPTZ, 'bf79b5f0f1edb86dd775aa0bdf90c206eb897430280d2d7fcde3d67c43e65989'::TEXT, ARRAY[563]::BIGINT[]),
    (503::BIGINT, 'Explica muy bien y le hace entender a uno porqué hace las cosas antes de explicar el procedimiento, también le enseña a usted como lo que esta aprendiendo le sirve a futuro. Los quices son duros pero esto es por su bien, es para que el examen se le haga más fácil.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-11-07T00:00:00+00:00'::TIMESTAMPTZ, '954f4649e7dae3231ed463c1671a5042e7ec321593d17811e8dda5074ee9e921'::TEXT, ARRAY[563]::BIGINT[]),
    (503::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Aspectos de calificación claros']::TEXT[], '2023-10-25T00:00:00+00:00'::TIMESTAMPTZ, 'f3c3155311ba38ef5b7f49294f3e74d72a70f1836bf1f658d8a51a96ce21043b'::TEXT, ARRAY[563]::BIGINT[]),
    (503::BIGINT, 'Si no tiene buenas bases no lleve con él, es prepotente a la hora de resolver dudas y siempre dice que eso es algo que deberíamos saber, no tiene paciencia. Las clases son muy pesadas y los quices son mortales.'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Exámenes retadores']::TEXT[], '2023-09-25T00:00:00+00:00'::TIMESTAMPTZ, '6933f8f1a6ac6377d7ebe211da6a9bf19def3952f7e85cff9f8f3c215e74f769'::TEXT, ARRAY[563]::BIGINT[]),
    (503::BIGINT, 'El profe explica bastante claro, e incluso da escenarios de la vida real en donde se aplica la materia. Cuando ve que uno le pone, hace mas quices para ayudar a uno subir la nota. Hace muchos ejemplos para que podamos esperar alguno de ellos en los exámenes'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-08-21T00:00:00+00:00'::TIMESTAMPTZ, '3c52d16f52094524a936c65b7f5783ea767d264ba8e00a3b1806de4a8e3fa587'::TEXT, ARRAY[563]::BIGINT[]),
    (503::BIGINT, 'Califica muy duro y los ejercicios que pone en clase no se parecen en nada a los del examen'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-24T00:00:00+00:00'::TIMESTAMPTZ, '5e355900a820c9636b39f30582ada4a02ca44d595723c44479a3530b70909769'::TEXT, ARRAY[935]::BIGINT[]),
    (503::BIGINT, 'Explica súper bien por lo que es fácil entender, sin embargo, superior es un curso que requiere mucha práctica y capacidad de visualización entonces si no se estudia puede ser complicado. No hace muchos quices y valen bastante. Tiene un canal de YouTube con clases que sirven para repasar.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, '287d7d5c41aca658778c5d8f41201d805ee50c15121ba1269669284d769e4bb7'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('20','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'af0e4f2e7e5d3297a4013f085d3cef9b80c77759ae4d2a9e22f12f25c968b73b'::TEXT, ARRAY[563]::BIGINT[]),
    (503::BIGINT, 'Aprovecha el tiempo de la clase, pasa los pdfs de la semana para que cuando uno llegue a la clase este preparado. Acompaña sus explicaciones formando la teoría poco a poco, no entra de golpe, sino que relata un cuento y capta la atención del estudiante. Pueden pasar a ver sus vídeos en YouTube.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'e0ee0b36870e463e9df14e5ecd159c2d060c4920124aa18490f7a3b42cb8e23e'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Pésimo profesor, califica muy duro y no es accesible en la clase, cada vez que uno consulta dice que es algo que deberíamos saber y responde de forma prepotente'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'e44400f1a28b549c976a36181521d3690f1a63ceeae04437f9852ea953dbe99a'::TEXT, ARRAY[935]::BIGINT[]),
    (503::BIGINT, 'Excelente profesor, se preocupa de que el estudiante entienda el tema, los quices son bastante durillos, pero con este profe se pasa la materia bien, totalmente recomendado, matricular con él mate general es lo mejor, 10/10'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-16T00:00:00+00:00'::TIMESTAMPTZ, '34f4ed9f932f9dce235210f7470a5167992b806a9e62ef77332533e6ba6e5c8e'::TEXT, ARRAY[563]::BIGINT[]),
    (503::BIGINT, 'El profe al principio lo pone nervioso a uno porque se ve muy exigente, pero se aprende super bien, se disfruta la clase y se nota que le gusta enseñar. Los quices son un poco rudos, pero hacen que el examen se vea muy fácil en comparación'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'af60e2231c2b0df6ba8f06bcd65bf36a2816f4b5f5151fca41c21cd0ff9c3600'::TEXT, ARRAY[563]::BIGINT[]),
    (503::BIGINT, 'El mejor de mejores.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2023-06-14T00:00:00+00:00'::TIMESTAMPTZ, '2358f81e44d48a6a14e2899075d5bffb49ce6d75b6bddf502acc5cb086005285'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Él es muy buen profesor, explica bien, ejemplifica los temas muy bien, busca ayudar a los estudiantes siempre que pueda, eso si, los quices pueden llegar a ser muy complicados si usted no practicó/estudió, pero realmente le ayuda en los exámenes, llegan a ser más fáciles en comparación.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Clases excelentes']::TEXT[], '2023-06-08T00:00:00+00:00'::TIMESTAMPTZ, '9f3fbf8907944eec7b85078b289337b049d86d98bf1cd3b614d2781e7fca157f'::TEXT, ARRAY[563]::BIGINT[]),
    (503::BIGINT, 'Es un excelente profesor y profesional, se le nota que lo suyo es enseñar y enseñar bien. Los quices son un tanto difíciles, si usted no estudio le va a costar pasarlos, sin embargo eso hace que los exámenes parezcan un chiste. Califica a como explica.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2023-05-31T00:00:00+00:00'::TIMESTAMPTZ, '159f483abd6220cf4f84e8f4faa74908d71cdc8a9c4c6a51b0c06a25921d9988'::TEXT, ARRAY[563]::BIGINT[]),
    (503::BIGINT, 'El profe es muy muy bueno, califica duro, pero si usted quiere aprender mate, matricule con él, va a ir majado en los quices pero va a volar en los parciales.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-05-31T00:00:00+00:00'::TIMESTAMPTZ, '00e447c61bb73d8201d10e2f7b75471c452eff7f7e03fbc8e932abc4dde31411'::TEXT, ARRAY[563]::BIGINT[]),
    (503::BIGINT, 'Es increíble, lo amo, estoy enamorada de él, explica demasiado bien, hace todos los ejemplos que usted ocupa, es muy agradable, quisiera quedarme en mate solo para tener que volver a llevar con él. El mejor profe del Tec simplemente'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-05-17T00:00:00+00:00'::TIMESTAMPTZ, '661dbfe7f4ae4a6f878cac21e87c8a614977013820cf720314f7b101dc792950'::TEXT, ARRAY[935, 923]::BIGINT[]),
    (503::BIGINT, 'El profe es una teja de persona, explica súper bien y si no entendió se devuelve al inicio si es necesario. Si usted pone de su parte aprende demasiado, eso sí, los quices son un toque duros entonces si no estudió ni lo haga.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2023-01-31T00:00:00+00:00'::TIMESTAMPTZ, '9a2bf78f26eaf834a9783338208823c5a9ad627bb09abf3ba2654982320fde62'::TEXT, ARRAY[563]::BIGINT[]),
    (503::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2023-01-25T00:00:00+00:00'::TIMESTAMPTZ, '756527d9796ab2124f337bb3b30d136ff3ca6c30142fe4252384416e1e812e00'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-12-14T00:00:00+00:00'::TIMESTAMPTZ, '3ae26d23769382be15a8b26ad230bd11a03868add7bc560102c35b1b871b6e9b'::TEXT, ARRAY[563]::BIGINT[]),
    (503::BIGINT, 'Es un excelente profesor, explica extremadamente bien la materia y prepara sus estudiantes para mas alla del curso como tal. El unico pero son los quices porque son mortales, sino estudió mejor ni lo haga'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2022-12-01T00:00:00+00:00'::TIMESTAMPTZ, '51799deb48f32f82df0681fe59181d2c6518a708bc75fb1d0af5ea5414fe7eca'::TEXT, ARRAY[563]::BIGINT[]),
    (503::BIGINT, 'Como persona y profesor es excelente, explica super bien y repite las veces que haga falta, si usted pone de su parte va a aprender demasiado, los quices son difíciles y califica duro estos y los exámenes.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes']::TEXT[], '2022-11-30T00:00:00+00:00'::TIMESTAMPTZ, '8272e2e07d82f0dbf146dc9ab4be503f14e0a2112600208dfb7062265dd4d95e'::TEXT, ARRAY[563]::BIGINT[]),
    (503::BIGINT, 'Es el mejor profe de Mate del Tec, sus clases son muy entretenidas, hay que poner atención, pero las explicaciones que da se adaptan muy bien a los temas y la relación con ingeniería.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Aspectos de calificación claros']::TEXT[], '2022-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'b51df3838e93056ac222eae32bc739cc5db8e934f866c4f898ec8b7456259cb6'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'El profesor Juan José, sin duda alguna es un excelente profesional. Sin embargo, si va a llevar el curso con él, tenga en cuenta que tiene que prepararse muy bien para los quices que él hace, porque suelen ser difíciles. Así que, ponga atención, practique la materia, evacúe dudas y le irá bien.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2022-11-17T00:00:00+00:00'::TIMESTAMPTZ, '0e76dc9b91034f4937b49fff61223f4ed1393c074097d7775f8dc4d67d25ef28'::TEXT, ARRAY[563]::BIGINT[]),
    (503::BIGINT, 'El mejor profe de mate con mi vida. Explica muy bien, está atento a dudas. Los quices son medio complicados, entonces prepararse bien. Pero resuelve varios ejercicios de examen en clase, junto con unas explicaciones buenísismas. Matricule sin miedo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-11T00:00:00+00:00'::TIMESTAMPTZ, '9efd0a3189a5db7f1fc9c1ab38b1a66412d2281545312cb12eedc3afb87184f8'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'El mejor profe de Mate en la faz de la Tierra'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-10-13T00:00:00+00:00'::TIMESTAMPTZ, 'd7f5c274de77805c35178c979917b43404de1d6857646ee64a2a29eebbc16ad3'::TEXT, ARRAY[935]::BIGINT[]),
    (503::BIGINT, 'No es un mal profesor, es claro, tiene buen material para repasar y resuelve dudas siempre que uno se lo pida. Pero siento que debería tener más paciencia con los estudiantes con adecuación. Muchos tenemos dificultades para entender las explicaciones a la primera. No es que"no nos interese el tema."'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2022-07-02T00:00:00+00:00'::TIMESTAMPTZ, 'a317cbac5cce10264c6db9f07a3736dcb675c71386761a250567a2a3dbc8b6e4'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'El mejor profe que he tenido en Cálculo. Ya las clases están grabadas por lo que es cuestión del estudiante de verlas y hacer algo de práctica, y una de la dos clases era sincrónica para hacer más ejercicios que le servian a uno para las tareas y examenes. Es un curso dificil pero gracias a él pasé'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'cb3708cb58c7803378bf56792b97a69aa59ed7b7ff74c1e3635dd20819d968d4'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Explica súper claro y siempre está dispuesto a ayudarlo a uno. Los quices que hace son muy difíciles entonces hay que estudiar bastante. Uno de los mejores profes de la escuela de mate!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2022-06-21T00:00:00+00:00'::TIMESTAMPTZ, '008d25a2cf44f2bf6faae314bb1078799b5834a7d68c2502b4ffeab268175ab3'::TEXT, ARRAY[935]::BIGINT[]),
    (503::BIGINT, 'Es buen profe, explica bien y es demasiado ordenado pero los quices que hace son peor que los parciales de cátedra.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2022-06-14T00:00:00+00:00'::TIMESTAMPTZ, '9694aefdfcc32570f6081871879f3cc9d63cec40a93ef37e4475b7d4993251c8'::TEXT, ARRAY[935]::BIGINT[]),
    (503::BIGINT, 'Explica muy claro, comparte los apuntes y graba todas las clases. Los quices del profe valen 20% de la nota y son más dificiles que los de cátedra, además hizo 3 en las últimas 4 semanas del semestre, entre el segundo y tercer parcial.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Brinda apoyo']::TEXT[], '2022-06-13T00:00:00+00:00'::TIMESTAMPTZ, '9af1f841e71f8efd310104d6f6bd76292ea5d1cd5d69f3480995a34e7eb78676'::TEXT, ARRAY[935]::BIGINT[]),
    (503::BIGINT, 'El l mejor profe que he tenido, siempre brinda apoyo para lo que uno necesite incluso cuando tenia dudas de ecuaciones diferenciales me ayudaba aunque no fuese alumno de el en ese curso ademas de que las clases de el son muy buenas y como organiza los pdf y videos es genial recomendado'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Aspectos de calificación claros']::TEXT[], '2022-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'b687ad67658e5d39b19e109763d2e1cb282d9bd15089aff9507823b35b71eabc'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Le gusta mucho ser profesor y lo que enseña, explica muy bien. Sus evaluaciones son extremadamente largas y difíciles (mayor dificultad que los exámenes de cátedra). Hace dos quices complicados en la semana del examen, lo que hace que llegue uno cansado al examen.'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Clases excelentes', 'Exámenes retadores']::TEXT[], '2022-06-12T00:00:00+00:00'::TIMESTAMPTZ, '5d4b13e4dee4db8c751bdc7262d9ccde912636ec43e1f230cddf1e19b6997955'::TEXT, ARRAY[935]::BIGINT[]),
    (503::BIGINT, 'Es un excelente profe, muy amable, atiende rápido el telegram, ordenado y clases con ejercicios muy útiles . Además, brinda un excel muy completo con el link de los videos, pdf y dividido por temas y parciales, lo cual hace que facilite mucho el estudio. Lo recomiendo sin duda.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-06-11T00:00:00+00:00'::TIMESTAMPTZ, 'e3655f0b17408d3c2f6c46819de2695ee8b77ed6e30fc4474d70719c36824d08'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Explica bien pero los quices son terribles, a todos les va mal y a el no le importa Es el primer semestre dando ecuaciones virtual y no sabe como hacer quices No matricule con el ya no es el mismo de antes'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2022-06-09T00:00:00+00:00'::TIMESTAMPTZ, '5a55c881675b0f540df493d0c7da1baabdb1726a8380cd08a03b35cae8314352'::TEXT, ARRAY[935]::BIGINT[]),
    (503::BIGINT, 'Es dios'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-03-23T00:00:00+00:00'::TIMESTAMPTZ, 'bf1bdb9c4e5c90e639c4092b66a52dcccd0294e0458f18b6e77798d0704c549e'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'El profesor es excelente, explica la materia del curso superbién y se interesa por que los estudiantes entiendan correctamente los contenidos del curso.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-02-06T00:00:00+00:00'::TIMESTAMPTZ, '5e03beaa4b5077558365275b28a26798f52d1a485123d43988facc955107d5fa'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Trabaja muy bien, atento a dudas de los estudiantes y genera confianza para preguntar él clase'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-01-27T00:00:00+00:00'::TIMESTAMPTZ, 'c6aa010484eb1e81760b737c2b8e3e2ca0f1e036b26720bc36ce97579f54a0b7'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Excelente profe! Siempre está atento a dudas las cuales responde rápido. En Verano el curso es asincrónico. Las clases ya han sido grabadas previamente. Sin embargo, estas tienen mucho detalle, son explicadas de forma muy buena y son muy buena preparación para los exámenes.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-01-27T00:00:00+00:00'::TIMESTAMPTZ, '322b9fb9c05f9028272a7a5c29590b023c898966833e07d1b360019677a60816'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Atento a dudas por Telegram y en clase. Ordenado y rápido para calificar. La materia del curso está grabada en YouTube, busque el canal como "Juan José Fallas". Cuando nos conectábamos a clase por Zoom era para repasar dicha materia de los videos y dar recomendaciones adicionales. Buen profe!'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-01-27T00:00:00+00:00'::TIMESTAMPTZ, '2b70e8e75e19018d3fc154db7b05a6630dbb02290b0e34447311de0c97af200e'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Excelente profesor, llevaría todas las mates con el'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-01-27T00:00:00+00:00'::TIMESTAMPTZ, '0ff149c699e8ccfa57dc47dd28f4f3f0b1598504fda2b0f4de392201c43da392'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-01-27T00:00:00+00:00'::TIMESTAMPTZ, '8d7d35310176e35d8ea33c76ad29be30ccf20dc71d7ed3ada21b03406c25cabc'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Profe muy ordenado, siempre está para atender dudas y las clases son súper ordenadas. Tiene un Excel donde viene el cronograma de todas las actividades durante el periodo lectivo .'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-01-27T00:00:00+00:00'::TIMESTAMPTZ, '1791255747df6432937af74f79cebec65d3686d7f3edbc9cd142aaa2db7de9c5'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'El profe ya tiene las clases subidas a YT y lo que va a hacer es darle el link para que las vea a su ritmo. Hace quizzes cada fin de semana prácticamente, y los hace un sábado, algo que me parece demasiado molesto porque son quizzes de profe, no de cátedra.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchos exámenes']::TEXT[], '2022-01-20T00:00:00+00:00'::TIMESTAMPTZ, 'dd9fce9262976f1511195f17c204a08033449607c0f6fbc3a42f556fd2cd140b'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Tiene toda la materia del semestre grabada, complementa la materia con una clase sincronica a la semana en la que se realizan ejercicios, explica demasiado claro, si le preguntas algo siempre va a buscar la manera mas facil de que entiendas.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-12-05T00:00:00+00:00'::TIMESTAMPTZ, 'f75190e6cc04e9e86be47a89c7540991db423b5b42984d10a992b2b9e64b849b'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Es de los mejores profes del TEC, tiene una carpeta que comparte con los videos de la materia, escucha a los estudiantes y complementa los videos con una clase semanal donde explica ejercicios más para un examen virtual, los quizes son duros pero ayudan un montón para el examen.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2021-12-05T00:00:00+00:00'::TIMESTAMPTZ, '09d857015b7251d78110e26010372019572ceb11c5ce6cbbbe79a91e843c981c'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Un profesor excelente, tiene una carpeta con las clases asincrónicas donde explica muy bien la materia, además da una clase sincrónica semanalmente para complementar. Siempre escucha y ayuda a los estudiantes. Sus quizes son algo rudos pero igual lo recomiendo al 100%'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-12-04T00:00:00+00:00'::TIMESTAMPTZ, '18c6849c98c2286dd3f5c91bdfa6bc6703fe857b1bc7225d57fa377d7962fcaa'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'El profe tiene un repositorio EXELENTE con todas las clases del semestre pregrabadas con sus respectivos PDF de apuntes, el cual complementa con una clase sincrónica a la semana para dudas. La forma en la que explica no puede ser más clara 10/10. Quices del nivel de los exámenes de cátedra.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'fb28be0bea64b855d9f779d70a5a659cc60e5732d4b52cc677eb0d93c9a251d7'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Explica super bien, deja toda la materia clara, con ver las clases es suficiente para los exámenes, no dude en matricular con el, de los mejores profes que puede encontrar'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-12-02T00:00:00+00:00'::TIMESTAMPTZ, '52472016d190a346f96fa6aaf3d2e328a890eb591089e09e84455d6aa585b2d5'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Excelente profesor para cualquier materia de la escuela de matemática, le importa que el estudiante entienda realmente el tema.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2021-12-02T00:00:00+00:00'::TIMESTAMPTZ, '43d7d908d144817568941f37217678c3d0950f5f7f3494357c90657338bf4e66'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'El mejor curso de mate que he tenido, el profe es super ordenado y con lo que explica (siempre quiere que usted entienda bien el concepto y todo) es más que suficiente para que le vaya bien en los quices y exámenes.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'a19d9001107f09c5a1f0f7178ef43d0db5b73bdccf2b83ac7550dad17af989db'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Es súper ordenado. Ya tiene TODAS las clases grabadas y eso ayuda a que uno se ordene con el tiempo, es solo no de no olvidar verlas y llevarlas al día. Los quites son muy difíciles, más que los parciales.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2021-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'c80d94b06cd77133b52012dcba0b9efa82c85e7ff010332c5abfbc30fc83fabd'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'De los mejores peores que he tenido, el profe explica súper bien, es demasiado ordenado y siempre deja todo claro, me gusta mucho el material de apoyo que él hace porque de verdad es excelente y sirve montones, el profe siempre está para uno para cualquier duda, mega recomendado'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-11-28T00:00:00+00:00'::TIMESTAMPTZ, '070c9accc7d93c47638fce3dc8ee3ac3b6d8c15691f1945dfb4a7801d8b7bdf2'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Resulta un excelente profe si uno como estudiante es organizado para ver los videos del curso. Los quices son difíciles pero lo preparan perfectamente para el examen. Explica muy claro y es ordenado'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-11-27T00:00:00+00:00'::TIMESTAMPTZ, '225733aed74d72e3c039740001ffbc2a29f57e87747ac5f8a6c280aebeec5e04'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'En virtual fue súper ordenado y claro, está muy atento siempre a dudas. Las clases ya estaban grabadas y subidas entonces le daba más autonomía al estudiante con la materia. Igualmente una vez a la semana daba clase sincrónica con ejercicios muy completos. Prepara EXCELENTE para los exámenes 11/10'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-27T00:00:00+00:00'::TIMESTAMPTZ, '23bd42969981a275ba5736eeac152b8ae563957c394dbd0d0dadb417d76780df'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Los quices son rudos, pero si usted los hace a consciencia y luego toma el tiempo de corregir los errores post-retroalimentación, llega súper preparado al examen. Siempre atento a dudas, explica claramente y muy ordenado en apuntes y grabaciones.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'b1bfef9448f069a3601f63031dd831d2fd743f928467a6306790cedb6a72d54a'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'De los mejores profes! Con las clases es más que suficiente para los quices y el examen. Hace bastantes evaluaciones, pero esto ayuda si en alguna no salió bien. Volvería a martricular con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'e8758eab25e16cad5a3e915be35d975a5b14ba2b2a8701fd86524759f13188ca'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Uno de los mejores profes de mate que he tenido. Explica bastante bien, brinda muchos ejemplos que sirven para prepararse para los quices y exámenes. Usualmente responde rápido las dudas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'b8dbeb6dd09a33f6fe8e52b36219c42086d782f85d2c8ad8af77815293feb06f'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Explica muy bien, el profe es agradable y hace la clase muy amena. Los quices son un toque difíciles, pero lo prepara muy bien para los exámenes. Da una clase sincrónica, pero usted tiene disponible todas las clases asincrónicas para verlas en cualquier momento. Matricule con el sin miedo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-26T00:00:00+00:00'::TIMESTAMPTZ, 'ba88dcae9a90bb0f4a56d4b5bab09c623526620483b65e5b7f637648930691d8'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Es el mejor profe para cálculo superior. Las clases son asincrónicas, los videos ya están grabados entonces puedes verlos cuando tengas tiempo disponible y si no entiendes algo él siempre contesta muy rápido y te ayuda.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-11-26T00:00:00+00:00'::TIMESTAMPTZ, 'ea4569ce0101e24deb19a5ee093ed976019ee339c8d24b0f3a33be111e254113'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'El profesor es muy bueno explicando y con solo su explicación es más que suficiente para los exámenes. Además, los quizes y demás son muy llevaderos, en general súper recomendado. Importante tener en cuenta que el curso de CS es fácil pero es muy denso en materia, el profe lo sabe dividir muy bien'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-26T00:00:00+00:00'::TIMESTAMPTZ, '491caedeb4856dbf73e9ca3708ebe9c354a392d60fe45323f7a6e2ddc4aaa4f9'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Solamente creo que se podría apoyar con repaso o exámenes viejos y usar la segunda clase para hacer clases más al punto... a veces por falta de tiempo uno necesita ir al grano.. pero es muy interesante saber el trasfondo así podría dar puntos extra por teórico y lo usual por práctico'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-26T00:00:00+00:00'::TIMESTAMPTZ, '1485a4a6a9f7a67b62c7b2f1401e8ed6a1f2f6f698e203280a4a27d9f172b163'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Buena gente el profe, explica muy bien y sus clases son muy ordenadas y con bastante información'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-26T00:00:00+00:00'::TIMESTAMPTZ, 'f2ab1be61c571e2c0f75037f205aa5d4dc34f5af0effc8c449182b1b40a32eb3'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Excelente profesor de los mejores de la cátedra, explica súper claro. Con las explicaciones del profe y practicando un poco se pasa súper bien. Recomendado'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-22T00:00:00+00:00'::TIMESTAMPTZ, 'b6f4d8cf980b2bd66f69dcc299bf33d8e4a02fd5b4a2ccaa60b2964778a78a85'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Excelente y organizado, de lo mejor de la escuela. Con los videos que hace todo queda súper claro, no hace falta ver lo que sube la cátedra y no hay que practicar tanto para los exámenes. A veces es un poco chichoso, pero nada exagerado. Metan con él de fijo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'd747d1a89e318c5a12a3ebe346593f886e42be571beff635d8cd6f0edb964486'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Excelente profesor, su metodología es muy buena ya que los videos de las clases y un poco de practica, es muy fácil pasar el curso. El curso es fácil, pero como toda mate necesita de practica.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-22T00:00:00+00:00'::TIMESTAMPTZ, '33673c04ac8dc8ec01d0589f68f919a3a71943ba0526b4021b523c4a67c7b263'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Excelente profesor. Prepara las clases bien, explica super bien, atento a consultas (casi siempre las responde muy rápido) y en general, es MUY buen profesor.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-21T00:00:00+00:00'::TIMESTAMPTZ, '200c12ecdcca148c474561e2bda0e6b69c2ea8b0a9538edc317f24ebbb915470'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Un Dios, excelente profe, matricule lo que sea con él, dele sin miedo'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-14T00:00:00+00:00'::TIMESTAMPTZ, '911462afa8f14fb50795729255b20cd3f8469066526eabf2e0258b0e06e2488b'::TEXT, ARRAY[923]::BIGINT[]),
