    (503::BIGINT, 'Excelente profesor! Las clases son súper entretenidas. Prepara demasiado bien para los exámenes. Ni lo pensaría para matricular con él de nuevo!!!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2021-02-08T00:00:00+00:00'::TIMESTAMPTZ, '94660c6393189f46418d652b3b921167414d91a31a0e74bde90200d1e96a80a6'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Para Superior, el mejor profe que puede existir'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-05T00:00:00+00:00'::TIMESTAMPTZ, 'ce58aaecb259cff9df0b741ca99a184d6a13a47cb9830d703da264dd78ae6c84'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Explica súper bien, con solo ver la clase basta para pasar el curso'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2021-02-05T00:00:00+00:00'::TIMESTAMPTZ, 'b6b51dc3412864f59727bdcd5086538b1f89807bc716eea144bb294063c2a0d9'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Es un dios de la pedagogía, literal con solo estar sentado prestando atención a sus clases es todo lo necesario para pasar cualquier curso'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, 'ce6540b391a42a1ae40afa56225d627c9e53f29be0b1a83f3604518529a3de17'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Clases estupendas todo queda claro, evaluaciones al nivel del curso que ayudan a reforzar la materia, no son fáciles, pero sí va a clases y saca dudas se consigue sin dificultad'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, '470d1fb5c0ff9b03df086ee56c7f4de2fbbbe4d29715e93f9be8b3993848d233'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Excelente profesor. El curso no es fácil, pero el mae le da a uno todas las herramientas necesarias para las evaluaciones. Los quices que hace son la mejor preparación para el examen. Da las 2 clases sincrónicas a la semana, explica toda la teoría desde cero y hace muchos ejercicios. El mejor profe.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, 'b2aebd4994cd4544091667038d4d014e9cbbcdd9bb321483d259018960750ce6'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Un dios de la enseñanza. Con solo sus clases casi que es suficiente para prepararse para las evaluaciones. Clases excelentes, buena comunicación y aspectos de calificación claros.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, '0c99e79cd3398fc8102e91be67fe2eaf685fea9edf3014ed7120f4d69d3036bc'::TEXT, ARRAY[923]::BIGINT[]),
