    (503::BIGINT, 'El mejor profe de la escuela de mate , simpre da las clases semanalmente , explica de donde sale cada cosa , super claro , quices tipo examen y rápido calificando , no dude en meter con él'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, 'f1c274443f28bcb5685332b27c125ee7ba51d5be57d02e39da852a18e66ec599'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Simplemente es el mejor. Explica demasiado bien y busca que uno entienda.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-22T00:00:00+00:00'::TIMESTAMPTZ, 'f4356da03baa753fd0c04aed1cef8a9316ba2fa1dcc53c0a30361f97be510a7e'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Explica super claro, se emociona un montón virtual, aveces manda clases extra ya grabadas, pero es para explicarle bien todo'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-12-22T00:00:00+00:00'::TIMESTAMPTZ, 'c37311292f9b7f731960ff049c8b56d35d2f1fcb4de4a954a9d4a02b538bd63d'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Muy buen profesor, da la clase super clara. Uno de los profes sino que el unico que da la clase semana a semana. Las clases son grabadas y facilita el curso. Los quices son durillos pero el lo prepara bien.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '3fd05085f24ad9f215f69aadd506935cc65081e32270ee9526aa47eba9776fbe'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'El mejor profe de la escuela de mate, explica demasiado bien, las clases son super buenas e interesantes. Lo deja a uno bien preparado para los exámenes. Y con la modalidad virtual estaba dispuesto a ayudar a cualquier estudiante con dudas. Super recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-23T00:00:00+00:00'::TIMESTAMPTZ, 'e07fcf165051873b45b6b155f3223083b64f25913c542f0bad049e80ac0d5e9e'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Muy buen profesor, explica de la mejor forma, si puede matricular con él no lo dude.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Clases excelentes']::TEXT[], '2020-08-23T00:00:00+00:00'::TIMESTAMPTZ, '76b58e35fdc79f6c22454f1151fd8a4460cddad82230aca3263fa78d827098ec'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'Excelente profesor con solo ver las clases usted va listo para los exámenes, explica muy claro, si tiene la oportunidad de matricular con él, ni lo piense'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-08-23T00:00:00+00:00'::TIMESTAMPTZ, '5188d0a73486c480d8b069663002216e204a248258e42d6ced318e6abce07298'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Excelente profesor, de verdad se preocupa por dar la materia de manera clara (Incluso en modalidad virtual). Sus clases son suficientes para prepararse para el exámen. Sus quices son muy dificiles. Poco mas que agregar, recomendado 100%'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-22T00:00:00+00:00'::TIMESTAMPTZ, '404b3827c284977a50d1944d5f855db247e2cc791c8d9706420bec7efa3be5c6'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'Uno de los mejores profes que he tenido. Sea virtual o presencial. No deje pasar la oportunidad de recibir clases con él'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-21T00:00:00+00:00'::TIMESTAMPTZ, '7700f3beaad5004d8c1d4cf97caa1d2a5d7901fa8e15409106372eb449b6451b'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Todos los temas los explica súper claro y responde cualquier duda. Los quices no los vi que me sirvieran mucho para el examen pero al menos me ayudó a aclarar otros tipos de ejercicios. Pero solo con lo que explica en clases y un par de ejercicios de práctica se pasa fácil.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2020-08-21T00:00:00+00:00'::TIMESTAMPTZ, 'ba32b5f749084bfd5f667a20742a233a07d36d4ce8d5bdcdfc3fbfeac9da8c3e'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'Es un profe genial, le saca las lagrimas con los quices pero eso le ayuda a que sienta faciles los examenes, igual con esto de las clases virtuales el profe se esfuerza en hacerlo entender y si tiene dudas lo puede interrumpir un momento. (No se abuse interrumpiendo).'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-21T00:00:00+00:00'::TIMESTAMPTZ, '4a5d554065901496530e79afbd455e8654b87dcb1b6be2593eb413947d6a0402'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'A mi criterio el mejor profe de la escuela de mate. Sabe explicar la materia super bien, se preocupa porque uno aprenda, en clases hace ejercicios con la misma dificultad de un examen y muy similares, los quices son un poco durillos pero ayuda a llevar la materia al dia. Recomendadísimo. VIRTUAL'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-21T00:00:00+00:00'::TIMESTAMPTZ, 'aee8d77261b40b7723a4ef7737bca35f19e3c837bb3fc1e2957701ea6b278092'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'El mejor profe para llevarlo virtual, explica todo excelente y se preocupa porque uno aprenda. Los quizes son un poco rudos pero sin duda uno va más que preparado para los exámenes.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, 'c41f05ec699c5de7468dfc37dd7857c3829d09d2f5a4c924ced20c1de843eb07'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'Súper buen profe!! el profe perfecto para llevarlo en modalidad virtual. Explica demasiado bien y siempre busca que el estudiante aprende y entienda la materia. No dudaría en matricular con él'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, '524119a664b7dd3dca6595f04c797c8e910ae0d9d52843b93d067ae2ed66f53c'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'Excelente profesor! De forma virtual le brinda a uno todo tipo de recursos para poder llevar el curso de una manera más fácil.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, 'b1494ca0d6cc9eb5d6bc52cf8a55aafa9dd280a40380fbc0f04380fd4d1b57dc'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Las clases son excelentes, el único inconveniente es que va muy rápido pero uno aprende a seguirle el ritmo. Los quices se sienten más complicados que los examenes de la Cátedra pero no es nada que él no haya explicado. La calidad no se vio afectada por el semestre virtual.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Exámenes retadores']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, 'bb7f4b2f1d587e78fb39651857f857168774fd38b3de5c0556c80bb8fa2db705'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'En lo poco presencial que llevé fue un profesor excelente, y en modalidad virtual de todos los cursos que llevé fue el que mejor se adaptó. Súper organizado, ayuda un montón. Matricularía con él cualquier curso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-14T00:00:00+00:00'::TIMESTAMPTZ, '9eb674195a23850c343c51df705c593bad2578606a42e2ab9bdb7eecb738973e'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'Excelente profe tanto de forma presencial como virtual, las clases virtuales fueron excelentes, se preocupa por que todos entiendan y explica súper claro. Si tiene la oportunidad de matricular con él no lo piense dos veces.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-11T00:00:00+00:00'::TIMESTAMPTZ, '12fa7f50ff8905a407e401f58c61a708b21d2458162ad407f21776eb00f09dda'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'Excelente profesor. Sus clases, a pesar de ser virtuales, fueron súper claras. Explica la materia tan bien que la hace ver súper sencilla. Llevaría otro curso con él sin duda. Recomendadísimo. Un crack.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-04T00:00:00+00:00'::TIMESTAMPTZ, '2665a6f6ca2f94d6e03aebbf8f8f9e69f4b34096ff178dd36a33b79645ea528f'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Excelente profesor, tiene demasiada vocación y se preocupa por el estudiante. Siempre trata de ver todo como lo vería uno. Explica demasiado claro. Genial para clases presenciales y virtuales.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-07-31T00:00:00+00:00'::TIMESTAMPTZ, 'a2aca0c3299385311eb231a12f40981695de17df4c9f76c09089f4bc544f12ad'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'El profe es excelente. Se toma su trabajo muy seriamente y su proposito siempre es que el estudiante aprenda. Se pasa muy bien mientras uno tambien ponga de su parte y estudie bastante. Si tiene que llevar las clases virtuales, no lo piense dos veces y metase con el.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-07-30T00:00:00+00:00'::TIMESTAMPTZ, '5bd2255b7dff786bdb292b6f3ba77582abead2dd8aa30ca58ebb1cd00e2eaaf6'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'Excelente profesor tanto a nivel presencial como virtual, llevaría cualquier curso de mate con él. Explica super claro y lo prepara a uno mucho para los exámenes. Los quices son difíciles pero nada imposible si estudia lo que él ha enseñado. Lo recomiendo muchísimo, de mis profes favoritos.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-07-29T00:00:00+00:00'::TIMESTAMPTZ, 'dc35d600dfa1520ed9539ada7dac0be030cf2aaf36888371de5d47c16a60345e'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Intente llevar la materia al día porque da mucha materia en una sola clases. Las clases son largas pero son muy útiles y provechosas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-07-28T00:00:00+00:00'::TIMESTAMPTZ, 'f10c4a9379ff8a3d883400ac8a6a82712799a62174a2343d4793657d63a052be'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'Excelente profesor, explica la materia super claro y hace bastantes ejemplos; los quices son un poco complicados pero corresponden a la excelente calidad de clases que da; y por lo tanto, se llega muy bien preparado a los exámenes. Llevaría todos los cursos de mate con él sean presenciales o no.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-07-28T00:00:00+00:00'::TIMESTAMPTZ, 'f81bf5f86d9bd0950315e34f96d379c51f8c52a844df498608d5bf9909b5fd9d'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'Presencial o virtual las clases son de una calidad excelente. Lleva la material muy al día con conceptos y practicas, y, sobre todo se esfuerza para que los conceptos queden totalmente claros.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-07-28T00:00:00+00:00'::TIMESTAMPTZ, '258c376264455c0c53d68d25c2b2b735e939db35df4f602b7c55512e1982a1df'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'Muy buen profesor. Sean clases virtuales o presenciales hace que la materia quede lo más claro posible y da los ejemplos suficientes para entender.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-07-27T00:00:00+00:00'::TIMESTAMPTZ, 'a0c960110a0821d44f9e40f98f57c81a74cf5afcace9d1dea47a4b043808c857'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'No importa si da clases virtuales o presenciales, ambas son de excelente calidad, ayuda y hace todo lo posible para que se comprenda bien la materia, trae ya la clase preparada con ejercicios y siempre explica algo mas que ayuda. Sin duda un excelente profe, #delesinmiedo.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2020-07-24T00:00:00+00:00'::TIMESTAMPTZ, 'd1e71b09859360c5c1957857e15071aa9fd390aa2358bc2506573dbec76da831'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'El profe es muy dinámico en las clases, es cómico a su manera y hace la clase interesante. Explica super bien y si uno no entiende, él busca la manera de que usted entienda bien. Busca que aprendamos más allá, no solo para pasar un examen.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2020-07-24T00:00:00+00:00'::TIMESTAMPTZ, '8dbe6bdd5b27eb248126b614dd1a35157868c02eec81af839f486b784f6ab136'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'Excelente profesor, incluso para ser modalidad virtual. Realmente se preocupa por que el estudiante aprenda. Hace las clases muy dinámicas. Creo que califica normal, sin regalar nada pero tampoco castiga absurdamente. 100% recomendado, muy bueno (pero no se agrande profe jajaja, pura vida)'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2020-07-24T00:00:00+00:00'::TIMESTAMPTZ, '85623e9b1dd72df0e835157748e6894c97ec9e80cbd53a352233c5a153ea6e2d'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Muy buen profe, lo recomiendo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-07-23T00:00:00+00:00'::TIMESTAMPTZ, 'd8adfa45c3d6edb85c834ba071dd74db59251e606e97ff441b01b31826764c18'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Clases excelentes']::TEXT[], '2020-07-23T00:00:00+00:00'::TIMESTAMPTZ, '07b2c602760c5ec29a7e281a1dd4959ad6b0dcbb941219a93ac66d299b6330c7'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-07-23T00:00:00+00:00'::TIMESTAMPTZ, '5366155033f093a56ab51863ee7f8418bf68ce896c00a9a042cd3c2a85e943f8'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'Es un excelente profesor, para me enseñó mucho a lo largo del semestre, es muy cómico y hace las clases muy entretenidas y se aprende de una manera diferente a los demás profesores. Se aprende de manera profunda y entendible la materia, es genial en lo que hace y sin duda llevaría otro curso con él.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2020-07-23T00:00:00+00:00'::TIMESTAMPTZ, '36f1b1432d3d7fa050f4f5ad12d0b763baab61e5403366944e349b735f57d768'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'Es muy buen profesor y explica bastante bien y de manera detallada. En ocasiones es un poco grosero, muy probablemente sea por su personalidad pero igual???????????. De igual forma lo recomiendo, se aprende mucho, califica cómo se debe, ni fácil ni duro.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-07-23T00:00:00+00:00'::TIMESTAMPTZ, '23c2304de74b59d18c1e457e70000dc5cec6d8bae8243ecbeedb047d52d08c02'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Es un excelente profesor, y personalmente creo que el que no pase su clase es porque le cuesta la matemática, o que no le interesara el curso, personalemente mi único problema es que como da tantísimos ejercicios a veces no me daba tiempo de analisar, pero eso es algo mas personal.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2020-07-23T00:00:00+00:00'::TIMESTAMPTZ, 'f55b968ca4dd3edd98cad67d1c973e13cbcbc1e144a44572747ca5f7d8cbe02c'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'Si quiere pasar el curso metalo con este profe, súper estructurado y hace las clases muy detalladas y prepara perfecto para los exámenes'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-07-23T00:00:00+00:00'::TIMESTAMPTZ, '17b902bbe5468b863da24882e4d0074a470b3d5a33c19c941e10551f385b43b7'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'En la modalidad virtual la metodología que empleó fue excelente. Explica de manera clara y con bastantes ejemplos que preparan muy bien para el examen, da bastante material de apoyo. Recomendadísimo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-07-23T00:00:00+00:00'::TIMESTAMPTZ, 'a31823f6f4c64aa520d12ea77b892ad22a135f3701c830416a3fd17d14520d7b'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'El profe es buenísima nota, muy activo y mantiene clase muy bien. Da todo lo necesario para pasar. Recomendado ????????'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-07-23T00:00:00+00:00'::TIMESTAMPTZ, 'e3a946cb01e0201f2da018f954a350167cffa32dac126381826fb29d2268c2c7'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Muy buen curso. La manera de dar la clase facilita la comprensión de los temas. Lo único que diría es que tal vez los quices sería ideal que fueran con un poco de más puntos, como para no perder tanto en casi de fallar alguna pregunta. Por lo demás, muy buen profesor.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2020-07-23T00:00:00+00:00'::TIMESTAMPTZ, '266887bcdf81cdbee455ebf044ca245d2eea9013b318e3f1c4135087471e9ed5'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'Excelente profesor,ya sea da manera virtual o presencial. Uno de verdad aprende,siempre lleva la materia un paso más alla y explica cada tema con profundidad.Ademas hace muchos ejemplos en clases,por lo que uno va súper preparado a los exámenes.No dude en matrícular con el.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-07-23T00:00:00+00:00'::TIMESTAMPTZ, '5dd711ec356f41232015f840414c88a24bc608f46387f18d5fbc85c3b7cb8a8e'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'El profesor es bueno, sus clases realmente son muy completas de modo que cuando asistes solo debes prestar mucha atención a sus explicaciones, y como en todo luego el trabajo de un estudiante es practicar. Pero en sí te prepara bien para cualquier parcial, con la misma calidad que enseña, te exige.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2020-07-23T00:00:00+00:00'::TIMESTAMPTZ, '10e7593af4e35c9891ec15f512aa88fbef0e7e5438208690ec3797729081ad2d'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Al inicio tal vez toma un poco de tiempo acostumbrarse al ritmo de la clase porque es un poco rápido, pero es un excelente profesor, hace que las cosas se vean muy fáciles y se preocupa por el aprendizaje de los estudiantes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-07-23T00:00:00+00:00'::TIMESTAMPTZ, 'f77d93aa2f68d1ba008f880ba563f3f9263db082ff48874c19574a7d3c8d4c60'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'El profe explica muy bien, siempre trata de que todos entiendan. Con respecto a las clases virtuales logró adaptarse muy bien a la situación. Es exigente pero lo vale porque explica bien. Además, es muy comprometido con los estudiantes.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2020-07-23T00:00:00+00:00'::TIMESTAMPTZ, '04bc8427a48a6a73170913175882b9ef65debbdec38e77870d3d0973a57d644d'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-07-23T00:00:00+00:00'::TIMESTAMPTZ, 'b1e255cfe19505f9df86e011421c2990825ffe181e06d6b6038319c33803d40d'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'El profesor es muy bueno explicando y lo hace con muchos ejemplos que de verdad ayudan en el examen, se le nota el interés en la clase y porque los estudiantes aprendan, siempre procura responder cualquier duda que a los estudiantes se les ocurra. Muy recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2020-07-23T00:00:00+00:00'::TIMESTAMPTZ, 'f7d5f7c1a827b329acc0a26c064bceb860a34f50bde648f05420e0ad9cba20f2'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Excelente, ya sea para clase virtual o presencial , siempre trata de que el estudiante aprenda y le quede todo claro . Te prepara con ejercicios que pueden llegar a entrar un una evaluación. Recomendando'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-07-23T00:00:00+00:00'::TIMESTAMPTZ, 'a97d76b33fc1f8500320b041427dac4366aa4502c0ea0db3c77c4b02f4b5b41b'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'Excelente como profesor, busca siempre ayudar al estudiante y califica acorde al nivel de profesor que es, siempre buscando la excelencia del estudiante. Llevaría cualquier curso otra vez sin dudarlo con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2020-07-23T00:00:00+00:00'::TIMESTAMPTZ, '6b96df40e34616541712fe16485aea5429fdd7e1737c580619658ebaae501e70'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-07-23T00:00:00+00:00'::TIMESTAMPTZ, '6806b6d5a644f0e565dfe179ec14972e2f33a4a6ae0157527db9d39db3880969'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'Súper recomendado para clases virtuales y presenciales. El profe explica con mucha claridad y muchos ejemplos, los cuales ayudan bastante para los exámenes. Siempre procura que los estudiantes entiendan la materia y responde muy bien a las dudas.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2020-07-23T00:00:00+00:00'::TIMESTAMPTZ, '6aaeedea5b095edada180dbb9f1111129540660b6a4cfb04676b9d29ee3c19b6'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'Excelente profesor, explica muy bien y da bastantes ejemplos, se preocupa por preparar bien a los estudiantes para los parciales y los quices los hace de manera que ayuden a fortalecer aspectos importantes'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-07-23T00:00:00+00:00'::TIMESTAMPTZ, '6a1550cfe67e5dae0a356b39487ea815249cd398621c6271b228aec8f240eafd'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'Súper recomendado para clases virtuales.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'cadd8ad22c7a60d18bfd206a8854601295c6f6bed10bfde7d6284bc974ee45ee'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'El profe tiene una forma de dar clases sencilla y se concentra en que todos aprendan. Si todos los profes fueran así el Tec estaría volando. Si tiene el chance de matricular con él hágalo, el curso se vuelve fácil ya que lo explica muy bien.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-02-13T00:00:00+00:00'::TIMESTAMPTZ, 'ab5a98e9adffc592919a936596c495c6ea93a8ec9ecb6b2a427c5d6b9ca3bc9d'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Al principio cuesta acostumbrarse al ritmo del profe porque va muy rápido pero cuando uno se acostumbra más bien agradece que sea así porque siempre da tiempo de ver toda la materia bien y da chance de ver muchos ejemplos y oportunidades para sacar dudas.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2019-12-19T00:00:00+00:00'::TIMESTAMPTZ, '18dd4bf8d88a89f95dc1d4203c2016150f1772a15a5c2f59e786819ca72c925a'::TEXT, ARRAY[935]::BIGINT[]),
    (503::BIGINT, 'Muy buen profesor, las clases son intensas y lo mantienen a uno activo, explica todo lo necesario para pasar el curso de forma sobrada. A algunos no les gusta su sarcasmo, sin embargo, a mi me entretiene bastante.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-12-01T00:00:00+00:00'::TIMESTAMPTZ, '98b1ec441de3c4b0c7f9464ecdfe8fa3dd1e31f229bc41ca2b4653d7550494d3'::TEXT, ARRAY[935]::BIGINT[]),
    (503::BIGINT, 'Súper recomendado este crack. En casiones tiende a ser ofensivo, con sus gestos y respuestas, pero pienso que es su forma natural de ser. Por lo demás, póngale y usted pasa el curso con 90. Los ejercicios son duros, pero el examen es un queque con lo que él. Si puede matricular con él ni lo dude.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2019-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'f27d4f2b2af3a872575a394573c80f9deb7ce0d5da01e2fcf4ba415a5a9e6c84'::TEXT, ARRAY[935]::BIGINT[]),
    (503::BIGINT, 'El profe explica super bien, los ejercicios que se ven clase son mas difíciles que el examen por lo que se pasa super fácil, el profe tienen muy buen humor pero si usted es sensible ni lo mete porque se va a ofender'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-21T00:00:00+00:00'::TIMESTAMPTZ, '43ef0994a34c14a1889f9d11d074d90a8a610eb1516a1058451b8bfe8c42d6aa'::TEXT, ARRAY[935]::BIGINT[]),
    (503::BIGINT, 'Excelente profesor. Explica muy bien. Aplica bastantes quices, por lo que uno llega bien preparado para el examen. Basta estudiar únicamente de los ejemplos que da en clase, son mucho más rudos que los que vienen en el examen y son similares a los de los quices. Full recomendado.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-20T00:00:00+00:00'::TIMESTAMPTZ, '1d846df90daac98e7aebad01d94af8b2b59e8e7cfec962e782426c356301fe2a'::TEXT, ARRAY[935]::BIGINT[]),
    (503::BIGINT, 'Muy buen profe. Hay que ir al día con la materia y comprenderla bien para poder llegar afilado a la clase. Enseña de una manera clara y con todo lo necesario para ir a hacer el examen. Los quices son más difíciles que el examen lo que ayuda mucho para prepararse.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-20T00:00:00+00:00'::TIMESTAMPTZ, '0402a75a6ba3d6632f49666688a3aa5ba342b2ec8f81ccc2ffb9a934fae40f8f'::TEXT, ARRAY[935]::BIGINT[]),
    (503::BIGINT, 'Excelente profesor, explica muy claro y le saca provecho a las clases. Quices que lo preparan a uno para el examen y hacen que al final se tenga que estudiar menos para el parcial. Tiene una personalidad muy característica que hace vacilona la clase . Súper recomendado para álgebra y ecuaciones.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-20T00:00:00+00:00'::TIMESTAMPTZ, 'c4b64646458d6a6555c74a2f2752e6827ca6373619b50e8460112a98728a3d12'::TEXT, ARRAY[935]::BIGINT[]),
    (503::BIGINT, 'Explica muy bien toda la materia, hace muchísima práctica y el examen parace fácil por los quices. Lo único es que da las clases un poco rápido si uno no está acostumbrado y que es un poco juega de vivo (aunque con razón porque es muy buen profe)'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-20T00:00:00+00:00'::TIMESTAMPTZ, 'a3f63444171b778e6d52abd36decf7751965812f850f4de14164e0a7ea16ea34'::TEXT, ARRAY[935]::BIGINT[]),
    (503::BIGINT, 'En mi opinión es el mejor profesor de matemáticas del TEC. Da toda la materia con mucha claridad, los ejercicios en clase y quices te preparan para el examen. Se pasa super bien, si le prestes atención a los consejos que da en clase para estudiar. Un tema difícil lo hace ver sencillo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-20T00:00:00+00:00'::TIMESTAMPTZ, '8813e7a2ea434f3453f016aa8c198e2ac80213466ec8b74a7240eb112ea0ee5f'::TEXT, ARRAY[935, 923]::BIGINT[]),
    (503::BIGINT, 'Un señor profesor, si usted va a prestar atención y con actitud, pasa el curso sobre ruedas, en los exámenes vas más que preparada, ya que da suficientes ejemplos para abarcar todas las variables que se puedan dar Full recomendado tanto para Superior como para Ecua'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Clases excelentes']::TEXT[], '2019-11-20T00:00:00+00:00'::TIMESTAMPTZ, 'ed57369d4bb3db3e7b9be5742564d5764f302a96f5ceff7d74a0f048e059b725'::TEXT, ARRAY[935, 923]::BIGINT[]),
    (503::BIGINT, 'Excelente profesor, llevaría cualquier mate con él. Siempre busca la mejor forma de que a todos les vaya bien en los exámenes.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-20T00:00:00+00:00'::TIMESTAMPTZ, '40a053746bbc35ebe2ed7865c3dbcf149a5f9150c192c5c2d8be5cebe96d320b'::TEXT, ARRAY[935]::BIGINT[]),
    (503::BIGINT, 'Es un profe que sabe demasiado y lo logra transmitir a los estudiantes, da seguridad y ensena mucho. Clases vacilonas y muy claro al explicar. 10/10'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-20T00:00:00+00:00'::TIMESTAMPTZ, 'ebcf54bdbf5acb7db386dbca65f8ff2d9960a93b40fd40035bcd4af6be7b937e'::TEXT, ARRAY[935]::BIGINT[]),
    (503::BIGINT, 'Es muy buen profe, es preocupado, divertido y se nota el interés porque los estudiantes aprendan.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-04T00:00:00+00:00'::TIMESTAMPTZ, 'b0849bed438609dd5c1a39ad9b55109f05c0bd195c50b3fd10d704dc67033ea9'::TEXT, ARRAY[2444]::BIGINT[]),
    (503::BIGINT, 'No es muy profesor es muy arrogante y creído... La humildad la dejo botada, es triste ver que un profesional de tanta calidad se le baje esa calidad por su actitud'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, '8cb349fab8131422c6f68520dbc531af313158de3fd1e14effad8947cc014500'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'No me gustó. Explica con presentaciones y habla mucho y uno se pierde fácil. La verdad el curso es fácil, pero hay que estudiar o le va malísimo'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-24T00:00:00+00:00'::TIMESTAMPTZ, '3a415d09ea096d5e0a78a415c10f67149a2fbd1313a75a5e7e0a8cb393166bed'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Sencillamente el mejor profe de mate que he tenido, por mucho. Sabe DEMASIADO, es súper inteligente, explica todo super claro. Hace quices relativamente seguidos pero lo mantiene a usted al día. Meta con él sin pensarlo, es el mejor.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'e36ca3e51102768029231d9485bdf5e6d994c665fc62d33aa97c4173a294e09a'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'El mejor profe de mate que he tenido, explica súper claro, abarca ejercicios tipo examen y lo prepara a uno súper bien con eso, va un poco rápido así qué hay que estar en todas, pero lo vale, quices duros, meta sin miedo, póngale y con él se pasa sobrado'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2019-06-22T00:00:00+00:00'::TIMESTAMPTZ, '44294ea53946d62040d19e0386217c85f4d99f21da6adea458c3dcf4ebd78dac'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Muy buen profesor, sabe mucho y explica la materia con demasiada claridad. Es medio prepotente pero eso no influye en como explica. Los quices lo preparan bien a uno para el examen y como explica tan bien califica duro.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'b478bb3510d49bc3b7056da126987fe2ed1b42470ea0d2e1a9c3e4f502076280'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'Es algo prepotente a veces, pero se le sale sin querer, sobre todo cuando responde preguntas. Sabe DEMASIADO y da todo demasiado claro, eso sí va volando, si es de los que tiene que entender y luego copiar no se lo recomiendo tanto, pero califica normal, los quices son nivel examen.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'ffbfc5b601d1d5a119050c1ed4446e913f818c75cde80f78bd8d9e3b9d04df1f'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Los quices son un poco durillos, hay que sentarse a estudiar. Califica normal y es buena gente.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-17T00:00:00+00:00'::TIMESTAMPTZ, '77100a7df3b1f38772a745a7f0edb7c013248e8056295091f552ce1e236f145d'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'El Dios de las matemáticas. Solo hay que cuidarse un poco con los quices.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-17T00:00:00+00:00'::TIMESTAMPTZ, '76612bdf5a4d8f4727dac26f663f40876df54422d0c5122a8cd5098342cce66e'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'El mejor profesor de matemáticas. Demasiado recomendado, meta con él sin pensarlo. También es buenísimo para Superior.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-15T00:00:00+00:00'::TIMESTAMPTZ, '5f7b172ed373c42beb19def0b1a6c56638ae26de820adbb61756c6277998b01f'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'Explica muy claro, tanto la parte teórica como los ejercicios que hace. Los quices son nivel examen, por eso es importante prestar atención y llevar la materia al día. Sin duda, es uno de los mejores profes de la escuela de mate.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-01-28T00:00:00+00:00'::TIMESTAMPTZ, '95558f3f6c3794233cc79c8ef7ec69d3081fb71d63f4b326ba9b9908e10c7864'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Explica muy bien, pero califica muy duro.'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2019-01-16T00:00:00+00:00'::TIMESTAMPTZ, '7607dc45620e2ec11e69201c055a2a7fbaaddbfd82be3bbc9e87769cc09d426f'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Una de las grandes mentes de esta escuela, muy buen profe y va directo al grano siempre.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-04T00:00:00+00:00'::TIMESTAMPTZ, '17da34a8c441fd7b5df8d761f73136cbba984a2f2de5b31ae93f2f1b65cb92df'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Estudiando para los quices, poniendo atención en clases, en el momento de repasar se le va a hacer muy fácil.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-12-05T00:00:00+00:00'::TIMESTAMPTZ, '4754c88e4f1ac2bd341bba4eb08de212bc0fcaa7db41278d654fd0ef9ac46b53'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Da la materia de tal forma que usted solo necesita ir a clase y practicar un poco para salir bien en el examen. Tome buenos apuntes y el curso se pasa fácil. Bastantes quices nivel de examen, lo que obliga a llevar la materia al día, lo cual es conveniente.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'e929d80a73c24a36f190a58ef76b33c26deec4ca1700412c32652ed79bdcb71d'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Si va a todas las clases, el examen se le va a hacer muy fácil. Muy buen profe los quices son difíciles. Si se presta mucha atención no hace falta estudiar para el examen.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2018-11-30T00:00:00+00:00'::TIMESTAMPTZ, '0150d32440e32546b47484abe7dd43d9169c5bd75c7e131619331e86046e879d'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Hace pocos quices son super dificiles nivel examenes, explica super bien ejemplos tipo examenes pero demasiado rapido da clases con proyector, es super puntual, no deja tareas, es medio hp cuando alguien pregunta algo. Califica muy duro'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Exámenes retadores']::TEXT[], '2018-11-16T00:00:00+00:00'::TIMESTAMPTZ, '3e2c36cabd8b7986a32c38c70132a908cf3dbe9e5a881567df7dc8a7bcc1b207'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, '02f5fc8ab4eca7ae4770a6a7d54feac7e4010ba763a6062921a2d92454770cb9'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'Da toda la materia con claridad, si usted asiste a todas sus clases es muy fácil aprobar el curso sin estudiar más de 2 horas por examen! Califica justo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'fe55e08820005b934ca2cee635431386386f6ae5cc31e5764d49ea5eb75cbe07'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Muy recomendado, da lo necesario de la teoría y se dedica mucho a la práctica con ejercicios de examen. Con los ejemplos que él hace usted llega preparado para lo que sea que le salga en el examen. Califica justo y entrega las evaluaciones rápido.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-17T00:00:00+00:00'::TIMESTAMPTZ, '051bb59a55da695c947dc01879c8e2420e0accbca1d90547a468b3eb0fcb583e'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Muy ordenado, explica claro y resuelve muchos ejercicios tipo examen durante las clases. Si uno hace lo que le pide el curso se pasa fácil. Persona totalmente capacitada y brillante.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-14T00:00:00+00:00'::TIMESTAMPTZ, '4cba983ff5e8535762af468846909fc635ce5a70c8044b2a7642b97d580c5383'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'El profe explica demasiado bien la materia, resuelve muchos ejemplos en clase, deja ejercicios de práctica más difíciles que los del exámen y es demasiado ordenado con la materia, si ud estudia lo que él dice pasa sobrado, de las mejores opciones para este curso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'da64833edb96ea85f72ef470d44954409d3a3732f3b20127815819d5ef80792e'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'c7aa667313de63bfc281d71ecfad8cec714bd7db83a75fc26dc210f0cd61187d'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Clases excelentes']::TEXT[], '2018-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'fd7d067f77eb615986a4f7298645c0af8d0d7b5e3779ac89cc6e458363a8592e'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'El profe no cae bien pero da la materia muy clara. Califica muy duro en los exámenes pero poniendo atención y estudiando el curso se pasa. Hace muchos ejemplos tipo examen.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes']::TEXT[], '2018-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'ccbd10f5702819fca88add25811040eb230ab56681b5d82052784c1ecfb06331'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'Sinceramente puedo decir que este mae es el mejor profesor de toda la escuela de mate, si no logra entender con él creo que con nadie lo va a lograr xD El mae explica demasiado claro y hace muchos ejemplos tipo examen. Califica según lo que enseña y él enseña demasiado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-13T00:00:00+00:00'::TIMESTAMPTZ, '27c472e7127745013e3e292f56c8d48346663d650510af1e1634021bd301a68d'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Excelente profesor! Totalmente recomendado, de lo mejor en la escuela de mate!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-13T00:00:00+00:00'::TIMESTAMPTZ, '1a34cc5bc004bf6426bbd650a4f807be37b9ea6bc0fa021f8e0ed8245101f6fd'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'De lo mejor que puede tener la escuela de mate. Clases entretenidas y 100% provechosas. Mucho consejo/advertencia sobre errores comunes en los exámenes, mucho ejemplo nivel de examen. Los quices son más difíciles que los exámenes pero él prepara a ese nivel.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-12T00:00:00+00:00'::TIMESTAMPTZ, '678928c1ef973b3ac9c0f5981843461bc2650088ddebd6c711e6e13a4e51d760'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Excelente profe! La materia la explica demasiado clara, con solo prestar atención en clase es cuestión de practicar en casa y listo. Califica justo pero con lo que enseña, si uno falla es porque al chile quiere.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-12T00:00:00+00:00'::TIMESTAMPTZ, '17d9d8930986697be04de02819da404a79e8c71e3aed301b432f285e5385122c'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Excelente profe ! Da la materia un poco rapido pero hace muchos ejemplos de examen que vale la pena'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-12T00:00:00+00:00'::TIMESTAMPTZ, '878a8020348cd7f8fcbff24e68b51db62c6e56d730fa752e8f583040106e85d8'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Explica muy bien la materia. Los ejemplos que realiza contemplan todos los posibles aspectos que hay que considerar para el examen, y por ello quizá al mostrar varios tiene que ir bastante rápido, puesto que cada uno muestra un caso diferente.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'a9f9113df4b225eebdbc8187d1f2cd4f8dd677551cff2f23e591f62627690c71'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'El profe es súper excelente, explica lo necesario para el examen y siempre brinda muchos ejemplos. No regala puntos en los exámenes, es muy justo con la calificación.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2018-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'e8c017f1d23dd00386e6be22d9622d72bce89eab0eab2913c88ef78a67474279'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'El profe explica muy claro y da muchos ejemplos para el examen que son excelentes. Puede que vaya un poco rápido, pero en general es muy buen profe.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-12T00:00:00+00:00'::TIMESTAMPTZ, '7e8c649482eb19ba91ff03c0daa9338cb29b3219b97e7761ada16f1b07a8cf02'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Uno de los mejores profesores de la Escuela de Matemática. El curso se lo sabe de memoria. El que se queda con él es porque quiere, simple.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-12T00:00:00+00:00'::TIMESTAMPTZ, '27b5332d095115e1231fa5da2938a089a824d73c2ae259d0bef9d570b943e7b4'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'El profe no regala la nota, se la tienen que ganar, pero con lo bien que él explica no es difícil. Estudiar al día porque la materia es demasiada. La clase se hace vacilona por la forma de hablar del profe. Hace 2 quices por examen. Los ejercicios que da son más rudos que los del examen'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-02T00:00:00+00:00'::TIMESTAMPTZ, '8fde6ee997a87a7e6956c30085d636998eb0187eba3daa512c362a4d0327aef4'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'El profe da la materia con diapositivas, no es de los que pone y explica todo en la pizarra. Sabe demasiado pero es muy arrogante y la actitud deja mucho que desear de un profesor. A veces no termina el ejercicio porque: "está muy fácil no voy a terminar eso". No lo recomiendo.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-05-28T00:00:00+00:00'::TIMESTAMPTZ, '8c9f078ebc7ad7b73a5e1b9d2d70d0c8b3a214dd98a4e942a25c76488996a95f'::TEXT, ARRAY[634]::BIGINT[]),
    (503::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-05-27T00:00:00+00:00'::TIMESTAMPTZ, '2956c7555c8e6668225c09ebe88d2081d9bbcb0e61f2465de077d9581dc4b7c6'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Excelente profe para explicar, lo prepara a uno bien para los exámenes por lo que sorprenderse en un examen es poco posible, califica justo, no regala ni quita puntos'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-02-10T00:00:00+00:00'::TIMESTAMPTZ, '51cc09e61bf435cb8742a50c987185521d91443ca2cf3ac45eccb7946f5269cd'::TEXT, ARRAY[935]::BIGINT[]),
    (503::BIGINT, 'Profesor de vocación, explica claro y a lujo de detalle toda la materia, de los mejores de la escuela. Hace que uno le agarre gusto a la mate.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2018-01-30T00:00:00+00:00'::TIMESTAMPTZ, '421d3290553b6b7be5750378ae4f8b3d7cd49c8d00deaf1ccecf7c6666eeb281'::TEXT, ARRAY[923, 2444, 605]::BIGINT[]),
    (503::BIGINT, 'Genio, excelentes clases, prepara muy bien para los examenes, enseña para que usted entienda, califica justo y no pierde tiempo. No ayuda mucho en consulta y no suelta ni medio punto al final.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2018-01-27T00:00:00+00:00'::TIMESTAMPTZ, '8a24f14e8665248dc61e1792f8affb33fc8493f31e74f92b3c87941996e104f8'::TEXT, ARRAY[935]::BIGINT[]),
    (503::BIGINT, 'Como profesor es EXCELENTE! Las clases son excelentes, le dice a uno todos los detallitos que debe poner atención y lo va a uno guiando para hacer el examen perfecto. También enseña todos los trucos y se preocupa por que uno entienda el concepto y no solo resolver ejercicios. Califica Duro'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2018-01-25T00:00:00+00:00'::TIMESTAMPTZ, '5bcd85dd159d70b85ac5310f7e3ec6e4ccf1750b2b457c84aa173ad8f84963b8'::TEXT, ARRAY[923, 2444, 605]::BIGINT[]),
    (503::BIGINT, 'Exelente profesor, explica muy bien, prepara aun mejor para los exámenes, hace los quices necesarios, sin duda llevaría otro curso con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-01-02T00:00:00+00:00'::TIMESTAMPTZ, 'da1859387e03c8557931f96f7932e165df85ac05fa20ab4134ed97856f8ac9da'::TEXT, ARRAY[935]::BIGINT[]),
    (503::BIGINT, 'Explica muy claro, prepara demasiado bien para los exámenes y resuelve dudas sin problemas, es muy pedante pero eso no afecta en el aprendizaje en el curso'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2017-12-04T00:00:00+00:00'::TIMESTAMPTZ, '9080f54b89fa71886499def4e7c6c9e97d145f2fd7bc6cb8d570cf11a39e820e'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Explica bastante bien cada detalle y prepara muy bien para los exámenes. Es bastante repugnante, pero excelente profesor. Dicen que califica duro, pero me parece que califica normal, así que es una buena opción definitivamente.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2017-12-03T00:00:00+00:00'::TIMESTAMPTZ, '5c7ebd1ee4132612ac9d50bcb88e661933071567845f67a5f27ad0a7cf7fa5fd'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Un crack, Dios del cálculo, no hay forma de no entender, todo lo explica perfecto, hace bastante ejemplos tipo examen.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'f3daaaa43a0674eb8fc4c5964884079779604077165d983ba5f735c7b62ee6f3'::TEXT, ARRAY[923]::BIGINT[]),
    (503::BIGINT, 'Excelente profesor, solamente de no faltar a clases porque hace comentarios muy importantes para el examen'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2017-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'd186304ad958267a2e567bbfa9807bee7d30d42ec92392e04d3be856ea59aef0'::TEXT, ARRAY[923]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
